const lamps = await Entity.filter({type: 'lamp'});
const isDark = (new Date(await Entity.get('Weather', 'sunset')) <= new Date()) || (new Date(await Entity.get('Weather', 'sunrise')) >= new Date());

for (const lamp of lamps) {
  if (lamp.name === 'Garden lamp') continue;
  await Entity.set(lamp.name, 'state', 'off');
}
if (!isDark) { await Entity.set('Garden lamp', 'state', 'off'); }
